//! Explicit regeneration; tests never update committed expected files.
use horizon_engine::canonical::canonical_json;
fn main() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut paths: Vec<_> = std::fs::read_dir(root.join("../app/fixtures"))
        .unwrap()
        .map(|e| e.unwrap().path())
        .collect();
    paths.sort();
    let mut manifest = String::from(
        "// SPDX-License-Identifier: AGPL-3.0-only\n// Generated by cargo run -p horizon-parity --example generate-golden.\npub const FIXTURES: &[(&str, &str, &str, &str)] = &[\n",
    );
    for p in paths {
        let text = std::fs::read_to_string(&p).unwrap();
        let Ok(f) = horizon_app::parse_fixture(&text) else {
            continue;
        };
        let Ok(run) = horizon_app::run_fixture(&f) else {
            continue;
        };
        let name = p.file_stem().unwrap().to_str().unwrap();
        std::fs::write(
            root.join(format!("golden/{name}.run.json")),
            format!("{}\n", canonical_json(&run).unwrap()),
        )
        .unwrap();
        std::fs::write(
            root.join(format!("golden/{name}.export.json")),
            format!(
                "{}\n",
                canonical_json(&horizon_app::export(&f).unwrap()).unwrap()
            ),
        )
        .unwrap();
        manifest.push_str(&format!("(\"{name}\", include_str!(\"../../../app/fixtures/{name}.json\"), include_str!(\"../../golden/{name}.run.json\"), include_str!(\"../../golden/{name}.export.json\")),\n"));
    }
    manifest.push_str("];\n");
    std::fs::write(root.join("tests/support/fixtures.rs"), manifest).unwrap();
    let f = horizon_app::parse_fixture(
        &std::fs::read_to_string(root.join("../app/fixtures/A-drawdown.json")).unwrap(),
    )
    .unwrap();
    let mut v = serde_json::to_value(horizon_app::export(&f).unwrap()).unwrap();
    std::fs::create_dir_all(root.join("../app/test-data")).unwrap();
    v["run"]["status"] = serde_json::json!("partial");
    std::fs::write(
        root.join("../app/test-data/tampered-export.json"),
        format!("{}\n", canonical_json(&v).unwrap()),
    )
    .unwrap();
    v["export_format_version"] = serde_json::json!(2);
    std::fs::write(
        root.join("../app/test-data/unknown-format-export.json"),
        format!("{}\n", canonical_json(&v).unwrap()),
    )
    .unwrap();
}
